// Daily Gumroad uploader — uploads 10 skills per day automatically
// Reads from skills-index.json (generated by build-index.js)
// Tracks progress in upload-progress.json
// Designed for GitHub Actions (no local filesystem dependency)

const fs = require('fs');
const path = require('path');
const https = require('https');

const INDEX_FILE = path.join(__dirname, 'skills-index.json');
const PROGRESS_FILE = path.join(__dirname, 'upload-progress.json');
const DAILY_LIMIT = 10;

const accessToken = process.argv[2];
if (!accessToken) {
  console.error('Usage: node daily-uploader.js <gumroad_access_token>');
  process.exit(1);
}

function sleep(ms) {
  return new Promise(r => setTimeout(r, ms));
}

function loadProgress() {
  if (fs.existsSync(PROGRESS_FILE)) {
    return JSON.parse(fs.readFileSync(PROGRESS_FILE, 'utf8'));
  }
  return { uploaded: [], failed: [], lastRun: null };
}

function saveProgress(progress) {
  progress.lastRun = new Date().toISOString();
  fs.writeFileSync(PROGRESS_FILE, JSON.stringify(progress, null, 2));
}

function getAllSkills() {
  const raw = fs.readFileSync(INDEX_FILE, 'utf8');
  return JSON.parse(raw);
}

async function uploadProduct(skill) {
  return new Promise((resolve, reject) => {
    const params = new URLSearchParams();
    params.append('access_token', accessToken);
    params.append('name', `MCP Skill: ${skill.name}`);
    params.append('price', '700');
    params.append('description', skill.desc || `MCP integration skill for ${skill.name}`);

    const body = params.toString();
    const req = https.request({
      hostname: 'api.gumroad.com',
      path: '/v2/products',
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' }
    }, res => {
      let body = '';
      res.on('data', d => body += d);
      res.on('end', () => {
        try {
          const json = JSON.parse(body);
          if (json.success) resolve(json.product.short_url);
          else reject(new Error(json.message || 'API error'));
        } catch (e) {
          reject(new Error(`Invalid response: ${body.substring(0, 100)}`));
        }
      });
    });
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

async function main() {
  const progress = loadProgress();
  const allSkills = getAllSkills();
  const uploadedSet = new Set(progress.uploaded);
  const failedSet = new Set(progress.failed);

  const pending = allSkills.filter(s => !uploadedSet.has(s.dirName) && !failedSet.has(s.dirName));

  if (pending.length === 0) {
    console.log(`All ${allSkills.length} skills uploaded! Nothing to do.`);
    return;
  }

  const batch = pending.slice(0, DAILY_LIMIT);
  console.log(`\n=== Daily Upload: ${batch.length} skills ===`);
  console.log(`Progress: ${uploadedSet.size}/${allSkills.length} uploaded, ${pending.length} remaining`);

  for (const skill of batch) {
    try {
      const url = await uploadProduct(skill);
      console.log(`✓ ${skill.name} → ${url}`);
      progress.uploaded.push(skill.dirName);
    } catch (err) {
      console.error(`✗ ${skill.name}: ${err.message}`);
      progress.failed.push(skill.dirName);
    }
    saveProgress(progress);
    await sleep(1500);
  }

  const remaining = pending.length - batch.length;
  console.log(`\nDone for today. Total: ${progress.uploaded.length}/${allSkills.length}`);
  if (remaining > 0) {
    console.log(`${remaining} skills remaining (~${Math.ceil(remaining / DAILY_LIMIT)} days left)`);
  }
}

main().catch(console.error);
